:1792318500},{"id":"SIM-512-008142","entered_at":1792317600,"exited_at":1792326000},{"id":"SIM-512-008143","entered_at":1792317900,"exited_at":1792323600},{"id":"SIM-512-008144","entered_at":1792318800,"exited_at":1792322400},{"id":"SIM-512-008145","entered_at":1792319700,"exited_at":1792325100},{"id":"SIM-512-008146","entered_at":1792319700,"exited_at":1792322700},{"id":"SIM-512-008147","entered_at":1792320000,"exited_at":1792322400},{"id":"SIM-512-008148","entered_at":1792320600,"exited_at":1792324800},{"id":"SIM-512-008149","entered_at":1792320900,"exited_at":1792322100},{"id":"SIM-512-008150","entered_at":1792320900,"exited_at":1792325400},{"id":"SIM-512-008151","entered_at":1792324200,"exited_at":1792329300},{"id":"SIM-512-008152","entered_at":1792328400,"exited_at":1792332300},{"id":"SIM-512-008153","entered_at":1792329900,"exited_at":1792332300},{"id":"SIM-512-008154","entered_at":1792332000,"exited_at":1792335300},{"id":"SIM-512-008155","entered_at":1792339200,"exited_at":null}]'::jsonb
) AS s(id text, entered_at double precision, exited_at double precision)
CROSS JOIN public.qpark_settings cfg
WHERE cfg.singleton AND s.exited_at IS NOT NULL;

DO $import$
DECLARE
  actor_id uuid;
  imported integer;
BEGIN
  IF (SELECT count(*) FROM qpark_dummyml_expected) <> 8154 THEN
    RAISE EXCEPTION 'Expected 8154 completed dummy visits and existing QPark settings';
  END IF;
  SELECT id INTO actor_id FROM public.qpark_staff
  WHERE active AND role IN ('ADMIN','PETUGAS')
  ORDER BY (username='petugas') DESC, (role='PETUGAS') DESC, created_at, id LIMIT 1;
  IF actor_id IS NULL THEN
    RAISE EXCEPTION 'No active QPark staff account; no accounts or passwords will be created';
  END IF;
  IF EXISTS (SELECT 1 FROM qpark_dummyml_expected WHERE exited_at > now() OR exited_at < entered_at) THEN
    RAISE EXCEPTION 'Dummy timestamps are invalid or in the future';
  END IF;

  INSERT INTO public.qpark_parking_sessions
    (id,plate,vehicle_type,hourly_rate,entered_at,entered_by,state,exited_at,exited_by)
  SELECT id,plate,vehicle_type,hourly_rate,entered_at,actor_id,'COMPLETED',exited_at,actor_id
  FROM qpark_dummyml_expected
  ON CONFLICT (id) DO NOTHING;
  GET DIAGNOSTICS imported = ROW_COUNT;

  -- Any collision rolls back ALL inserts; never overwrite a pre-existing session.
  IF EXISTS (
    SELECT 1 FROM qpark_dummyml_expected e
    LEFT JOIN public.qpark_parking_sessions p ON p.id=e.id
    WHERE p.id IS NULL OR p.plate IS DISTINCT FROM e.plate
      OR p.vehicle_type IS DISTINCT FROM e.vehicle_type
      OR p.entered_at IS DISTINCT FROM e.entered_at
      OR p.exited_at IS DISTINCT FROM e.exited_at
      OR p.state IS DISTINCT FROM 'COMPLETED'
  ) THEN
    RAISE EXCEPTION 'Dummy ID collision: existing data differs; transaction rolled back';
  END IF;

  IF imported > 0 THEN
    INSERT INTO public.qpark_audit(entity_id,event_type,actor,server_time,result)
    VALUES ('qpark-dummyml-v1','SIMULATION_IMPORT','SIMULATION',now(),
      jsonb_build_object('source_kind','simulation','seed',512,'imported',imported,
        'prefix','DUMMYMLV1-','linked_staff',actor_id,
        'note','Historical dummy only; no actual parking or payment occurred')::text);
  END IF;
  RAISE NOTICE 'Added % dummy visits; existing visits preserved', imported;
END $import$;
COMMIT;

-- Verify results: total_dummy must be 8154 and active_dummy must be 0.
SELECT count(*) AS total_dummy,
       count(*) FILTER (WHERE state <> 'COMPLETED') AS active_dummy,
       min(entered_at) AT TIME ZONE 'Asia/Jakarta' AS first_entry_wib,
       max(exited_at) AT TIME ZONE 'Asia/Jakarta' AS last_exit_wib
FROM public.qpark_parking_sessions
WHERE starts_with(id, 'DUMMYMLV1-SIM-512-');
